    descriptionAdvanced: {
      de: "Das Camp de la Transportation in Saint-Laurent-du-Maroni war das wichtigste Durchgangslager für Sträflinge, die während der Kolonialzeit nach Französisch-Guayana deportiert wurden. Die im Jahr 1852 errichtete Anlage diente als zentraler Ankunftsort, an dem die Gefangenen registriert und auf die verschiedenen Arbeitslager im Landesinneren verteilt wurden. Die Architektur des Lagers mit seinen massiven Steinmauern, Wachtürmen und engen Zellen spiegelt die harten Bedingungen des Strafvollzugs wider, der bis 1953 in Kraft blieb. Zu den bekanntesten Insassen gehörte Henri Charrière, dessen Erlebnisse später die Grundlage für das Buch Papillon bildeten. Heute ist das Gelände als historisches Denkmal klassifiziert und beherbergt ein Museum, das die düstere Geschichte der Bagno dokumentiert. Besucher können die originalen Zellen, das Krankenhaus und die Verwaltungsgebäude besichtigen, die Zeugnis von einem Jahrhundert repressiver Justizpolitik ablegen.",
      hu: "A Saint-Laurent-du-Maroni városában található Camp de la Transportation volt a gyarmati korszakban Francia Guyanába deportált fegyencek elsődleges fogadóközpontja. Az 1852-ben alapított létesítmény központi érkezési helyként szolgált, ahol a foglyokat nyilvántartásba vették, majd szétosztották a belső területeken található különböző munkatáborokba. A tábor építészete a masszív kőfalakkal, őrtornyokkal és szűk cellákkal hűen tükrözi a büntetés-végrehajtás kegyetlen körülményeit, amelyek egészen 1953-ig fennálltak. Az egyik legismertebb fogoly Henri Charrière volt, akinek élményei később a Pillangó című regény alapjául szolgáltak. Napjainkban a terület történelmi műemléki védettséget élvez, és egy múzeumnak ad otthont, amely a Bagno sötét korszakát mutatja be. A látogatók megtekinthetik az eredeti cellákat, a kórházat és az adminisztrációs épületeket.",
      ro: "Camp de la Transportation din Saint-Laurent-du-Maroni a fost principalul centru de triere pentru deținuții deportați în Guyana Franceză în timpul epocii coloniale. Construit în anul 1852, complexul servea drept punct central de sosire, unde prizonierii erau înregistrați înainte de a fi distribuiți către diversele lagăre de muncă forțată din interiorul teritoriului. Arhitectura lagărului, cu zidurile sale masive de piatră, turnurile de veghe și celulele strâmte, reflectă condițiile extrem de dure ale sistemului penitenciar care a funcționat până în 1953. Printre cei mai cunoscuți deținuți s-a numărat Henri Charrière, ale cărui experiențe au stat la baza celebrului roman Papillon. Astăzi, situl este clasificat ca monument istoric și găzduiește un muzeu care documentează istoria sumbră a coloniei penitenciare (Bagno). Vizitatorii pot vedea celulele originale și clădirile administrative.",
      en: "The Camp de la Transportation in Saint-Laurent-du-Maroni was the primary processing center for convicts deported to French Guiana during the colonial era. Established in 1852, the facility served as the central arrival point where prisoners were registered and categorized before being distributed to various labor camps across the territory. The camp's architecture, featuring massive stone walls, watchtowers, and cramped collective cells, reflects the brutal conditions of the penal system that remained operational until 1953. One of its most famous inmates was Henri Charrière, whose experiences later inspired the semi-autobiographical novel Papillon. Today, the site is classified as a historical monument and houses a museum dedicated to documenting the dark history of the penal colony. Visitors can explore the original barracks, the hospital, and the administrative offices that stand as a testament to a century of repressive policy.",
      es: "El Camp de la Transportation en Saint-Laurent-du-Maroni fue el campo de tránsito más importante para los convictos deportados a la Guayana Francesa durante la época colonial. Construida en 1852, la instalación servía como punto central de llegada donde los prisioneros eran registrados y distribuidos a los diversos campos de trabajo en el interior del país. La arquitectura del campo, con sus macizos muros de piedra, torres de vigilancia y estrechas celdas, refleja las duras condiciones del sistema penitenciario, que permaneció en vigor hasta 1953. Entre los internos más conocidos se encontraba Henri Charrière, cuyas vivencias sirvieron posteriormente de base para el libro Papillon. Hoy en día, el recinto está clasificado como monumento histórico y alberga un museo que documenta la oscura historia del bagne. Los visitantes pueden visitar las celdas originales, el hospital y los edificios administrativos, que dan testimonio de un siglo de políticas judiciales represivas.",
      pt: "O Camp de la Transportation em Saint-Laurent-du-Maroni foi o campo de trânsito mais importante para os condenados deportados para a Guiana Francesa durante o período colonial. Construída em 1852, a instalação servia como ponto central de chegada, onde os prisioneiros eram registados e distribuídos pelos diversos campos de trabalho no interior do país. A arquitetura do campo, com as suas maciças muralhas de pedra, torres de vigia e celas estreitas, reflete as duras condições do sistema penal, que permaneceu em vigor até 1953. Entre os reclusos mais conhecidos contava-se Henri Charrière, cujas experiências serviram mais tarde de base para o livro Papillon. Hoje, o local está classificado como monumento histórico e alberga um museu que documenta a história sombria do degredo. Os visitantes podem visitar as celas originais, o hospital e os edifícios administrativos, que testemunham um século de políticas judiciais repressivas.",
      fr: "Le Camp de la Transportation à Saint-Laurent-du-Maroni était le principal centre de transit des bagnards déportés en Guyane française à l'époque coloniale. Établi en 1852, ce site servait de lieu d'arrivée central où les prisonniers étaient immatriculés avant d'être répartis dans les différents camps de travail de l'intérieur. L'architecture du camp, avec ses murs de pierre massifs, ses miradors et ses cellules exiguës, reflète la dureté du régime pénitentiaire qui resta en vigueur jusqu'en 1953. Parmi les détenus les plus célèbres figure Henri Charrière, dont le récit servit de base au livre Papillon. Aujourd'hui, le site est classé monument historique et abrite un musée documentant l'histoire sombre du bagne. Les visiteurs peuvent découvrir les cellules d'origine, l'hôpital et les bâtiments administratifs, témoins d'un siècle de politique pénale répressive.",
    },
