      ro: "Celebră insulă colonie penală unde au fost ținuți prizonieri politici precum Alfred Dreyfus.",
      en: "Famous penal colony island where political prisoners like Alfred Dreyfus were held.",
      es: "Famosa isla de la colonia penal donde estuvieron recluidos prisioneros políticos como Alfred Dreyfus.",
      pt: "Famosa ilha de colónia penal onde foram mantidos prisioneiros políticos como Alfred Dreyfus.",
      fr: "Célèbre île du bagne où furent détenus des prisonniers politiques comme Alfred Dreyfus.",
