      hu: ["Az építkezés 1825-ben kezdődött", "A templom 1833-ra készült el teljesen", "1933. november 9-én szentelték katedrálissá", "A harangtornyot 1952 és 1954 között építették hozzá", "1992. október 29-én nyilvánították műemlékké", "A belső térben carrara-i márványoltár található"],
