      en: ["Construction began in 1825 by Father Guiller", "The main building was finished in 1833", "Consecrated as a cathedral on November 9, 1933", "The bell tower was constructed between 1952 and 1954", "Classified as a Monument Historique in October 1992", "Features a high altar made of Carrara marble"],
