      hu: "Történelmi aranybányászati aknák Saint-Élie-ben, amelyek a régió 19. századi aranylázát tükrözik.",
      ro: "Puțuri istorice de exploatare a aurului în Saint-Élie, reflectând goana după aur din secolul al XIX-lea a regiunii.",
      en: "Historic gold mining shafts in Saint-Élie, reflecting the region's 19th-century gold rush.",
      es: "Pozos mineros de oro históricos en Saint-Élie que reflejan la fiebre del oro de la región en el siglo XIX.",
      pt: "Poços históricos de mineração de ouro em Saint-Élie que refletem a corrida do ouro da região no século XIX.",
      fr: "Anciens puits d'extraction aurifère à Saint-Élie, témoins de la ruée vers l'or du XIXe siècle dans la région.",
