    descriptionAdvanced: {
      de: "L'Auberge des Orpailleurs liegt an der Straße nach Kaw im Osten von Französisch-Guayana und ist ein symbolträchtiger Ort, der eng mit der Geschichte des Goldrausches in der Region verbunden ist. Der Name erinnert an die 'Orpailleurs', die Goldsucher, die seit dem 19. Jahrhundert in den dichten Regenwald vordrangen, um in den Flüssen nach Reichtum zu suchen. Ursprünglich als einfacher Stützpunkt für Minenarbeiter und Entdecker gedacht, entwickelte sich die Herberge zu einem wichtigen Treffpunkt inmitten der Wildnis. Die Architektur ist typisch für die Region, wobei lokale Hölzer und traditionelle Bauweisen verwendet wurden, um den extremen klimatischen Bedingungen des Äquators standzuhalten. Heute fungiert der Ort nicht nur als Unterkunft, sondern auch als Bildungszentrum für Ökotourismus, das Besuchern die komplexe Beziehung zwischen menschlicher Wirtschaft und dem Schutz des Amazonas-Regenwaldes näherbringt. Die Geschichte der Goldgewinnung wird hier durch Berichte und Exponate lebendig gehalten.",
      hu: "A L'Auberge des Orpailleurs a Kaw-ba vezető út mentén található Francia Guyana keleti részén, és egy olyan ikonikus helyszín, amely szorosan kapcsolódik a régió aranylázának történetéhez. A név az „orpailleurs”-okra, vagyis azokra az aranymosókra utal, akik a 19. század óta hatoltak be a sűrű esőerdőkbe, hogy a folyók medrében szerencsét próbáljanak. Az eredetileg a bányászok és felfedezők egyszerű pihenőhelyeként szolgáló fogadó fontos találkozóponttá vált a vadon közepén. Építészete a régióra jellemző jegyeket hordozza: helyi fafajtákból, hagyományos technikákkal épült, hogy ellenálljon az egyenlítői éghajlat szélsőséges hatásainak. Napjainkban a hely nem csupán szálláshelyként üzemel, hanem az ökoturizmus egyik központja is, amely segít a látogatóknak megérteni az emberi gazdaság és az Amazonas-medence védelme közötti kényes egyensúlyt. Az aranybányászat emlékeit kiállítások és történetek őrzik itt.",
      ro: "L'Auberge des Orpailleurs este situată pe drumul către Kaw, în estul Guyanei Franceze, fiind un loc simbolic strâns legat de istoria goanei după aur din regiune. Numele face referire la „orpailleurs”, căutătorii de aur care, începând cu secolul al XIX-lea, s-au aventurat în pădurea tropicală densă pentru a găsi bogății în albiile râurilor. Inițial conceput ca un punct de sprijin simplu pentru mineri și exploratori, hanul a devenit un loc de întâlnire crucial în mijlocul sălbăticiei. Arhitectura sa este tipică regiunii, utilizând lemn local și tehnici tradiționale capabile să reziste condițiilor climatice ecuatoriale extreme. În prezent, locația funcționează nu doar ca unitate de cazare, ci și ca centru de educație pentru ecoturism, oferind vizitatorilor informații despre relația complexă dintre activitatea economică și conservarea pădurii amazoniene. Istoria mineritului este menținută vie aici prin exponate și relatări locale.",
      en: "L'Auberge des Orpailleurs is located on the road to Kaw in eastern French Guiana and is an iconic site closely linked to the history of the region's gold rush. The name honors the 'orpailleurs', or gold prospectors, who have ventured into the dense rainforest since the 19th century to search for wealth in riverbeds. Originally established as a simple outpost for miners and explorers, the inn evolved into a vital meeting point in the heart of the wilderness. Its architecture is typical of the region, utilizing local timber and traditional methods designed to withstand the extreme equatorial climate. Today, the site serves not only as lodging but also as an ecotourism hub, teaching visitors about the complex relationship between human industry and the preservation of the Amazonian rainforest. The history of gold mining is kept alive through local stories and exhibits documenting the arduous life of the prospectors.",
      es: "L'Auberge des Orpailleurs se encuentra en la carretera a Kaw, en el este de la Guayana Francesa, y es un lugar emblemático estrechamente vinculado a la historia de la fiebre del oro en la región. El nombre recuerda a los orpailleurs, los buscadores de oro que, desde el siglo XIX, se adentraban en la densa selva tropical para buscar riqueza en los ríos. Pensado originalmente como una base sencilla para mineros y exploradores, el albergue se convirtió en un importante punto de encuentro en medio de la naturaleza. La arquitectura es típica de la región, utilizando maderas locales y métodos de construcción tradicionales para resistir las condiciones climáticas extremas del ecuador. Hoy en día, el lugar funciona no solo como alojamiento, sino también como centro educativo para el ecoturismo, acercando a los visitantes a la compleja relación entre la economía humana y la protección de la selva amazónica. La historia de la extracción de oro se mantiene viva aquí a través de relatos y piezas de exposición.",
      pt: "L'Auberge des Orpailleurs situa-se na estrada para Kaw, no leste da Guiana Francesa, e é um local emblemático intimamente ligado à história da febre do ouro na região. O nome recorda os 'Orpailleurs', os garimpeiros que, desde o século XIX, penetravam na floresta tropical densa para procurar riqueza nos rios. Originalmente pensado como uma base simples para mineiros e exploradores, a estalagem tornou-se um ponto de encontro importante no meio da natureza selvagem. A arquitetura é típica da região, sendo utilizadas madeiras locais e métodos de construção tradicionais para resistir às condições climáticas extremas do equador. Hoje, o local funciona não apenas como alojamento, mas também como centro educativo para o ecoturismo, que aproxima os visitantes da relação complexa entre a economia humana e a proteção da floresta amazónica. A história da extração de ouro é mantida viva aqui através de relatos e exposições.",
      fr: "L'Auberge des Orpailleurs est située sur la route de Kaw, dans l'est de la Guyane française, et constitue un lieu emblématique étroitement lié à l'histoire de la ruée vers l'or dans la région. Son nom rappelle les orpailleurs, ces chercheurs d'or qui, dès le XIXe siècle, s'enfonçaient dans la jungle épaisse pour chercher fortune dans les rivières. Conçue à l'origine comme une simple base pour les mineurs et les explorateurs, l'auberge est devenue un point de rencontre important au cœur de la nature sauvage. L'architecture est typique de la région, utilisant des bois locaux et des techniques de construction traditionnelles pour résister aux conditions climatiques extrêmes de l'équateur. Aujourd'hui, le lieu sert non seulement d'hébergement, mais aussi de centre éducatif pour l'écotourisme, sensibilisant les visiteurs à la relation complexe entre l'économie humaine et la protection de la forêt amazonienne. L'histoire de l'extraction de l'or y est maintenue vivante à travers des récits et des objets exposés.",
    },
